1	import type {SessionEntry} from './session.js';
2	import type {SessionCursor} from './sessionStore.js';
3	
4	export interface UserMessagePayload {
5	  type: 'user_message';
6	  content: string;
7	}
8	
9	export interface PingMessage {
10	  type: 'ping';
11	  timestamp: number;
12	}
13	
14	export interface ListSessionsMessage {
15	  type: 'list_sessions';
16	  limit?: number;
17	  before?: SessionCursor;
18	}
19	
20	export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;
21	
22	export interface ConnectedMessage {
23	  type: 'connected';
24	  sessionId: string;
25	  message: string;
26	  examplePrompts: string[];
27	  resumed?: boolean;
28	  entryCount?: number;
29	  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
30	  resumeFailure?: 'expired' | 'unknown';
31	}
32	
33	export interface EntryUpsertMessage {
34	  type: 'entry_upsert';
35	  index: number;
36	  entry: SessionEntry;
37	}
38	
39	export interface EntryDeltaMessage {
40	  type: 'entry_delta';
41	  index: number;
42	  delta: string;
43	}
44	
45	export interface EntryCommitMessage {
46	  type: 'entry_commit';
47	  index: number;
48	}
49	
50	export interface ErrorMessage {
51	  type: 'error';
52	  code: string;
53	  message: string;
54	}
55	
56	export interface PongMessage {
57	  type: 'pong';
58	  timestamp: number;
59	}
60	
61	export interface EntrySkipMessage {
62	  type: 'entry_skip';
63	  index: number;
64	}
65	
66	export interface StreamEndMessage {
67	  type: 'stream_end';
68	}
69	
70	export interface SessionSummaryFrame {
71	  sessionId: string;
72	  createdAt: string;
73	  updatedAt: string;
74	  entryCount: number;
75	}
76	
77	export interface SessionListMessage {
78	  type: 'session_list';
79	  sessions: SessionSummaryFrame[];
80	}
81	
82	export type OutgoingMessage =
83	  | ConnectedMessage
84	  | EntryUpsertMessage
85	  | EntryDeltaMessage
