async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  historyEnabled: boolean,
  message: {limit?: number; before?: {updatedAt: string | number; sessionId: string}}
): Promise<void> {
  if (!historyEnabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
