      sessionId: s.sessionId,
      createdAt: typeof s.createdAt === 'string' ? s.createdAt : s.createdAt.toISOString(),
      updatedAt: typeof s.updatedAt === 'string' ? s.updatedAt : s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    log.error('ws', 'listFor error', {
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
      sessionId: session.sessionId,
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversation history');
  }
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

