async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  historyEnabled: boolean,
  message: {limit?: number; before?: {updatedAt: string | number; sessionId: string}}
): Promise<void> {
  if (!historyEnabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
    return;
  }

  if (!sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not available');
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, message);
    const sessions = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: typeof s.createdAt === 'string' ? s.createdAt : s.createdAt.toISOString(),
      updatedAt: typeof s.updatedAt === 'string' ? s.updatedAt : s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    log.error('ws', 'listFor error', {
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
      sessionId: session.sessionId,
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversation history');
  }
}

